create extension if not exists pgcrypto with schema extensions;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

create type public.profile_status as enum ('draft','published','hidden');
create type private.product_status as enum ('available','active','blocked','revoked');
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade, display_name text check(char_length(display_name)<=80), photo_path text, preferred_language text not null default 'pt-BR', created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.emergency_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,status public.profile_status not null default 'draft',preferred_name text check(char_length(preferred_name)<=80),birth_date date check(birth_date is null or birth_date>=date '1900-01-01'),pronouns text check(char_length(pronouns)<=40),blood_type text check(blood_type in ('A+','A-','B+','B-','AB+','AB-','O+','O-') or blood_type is null),allergies text check(char_length(allergies)<=1000),conditions text check(char_length(conditions)<=2000),medications text check(char_length(medications)<=2000),support_needs text check(char_length(support_needs)<=1000),medical_devices text check(char_length(medical_devices)<=1000),health_plan_name text check(char_length(health_plan_name)<=100),other_guidance text check(char_length(other_guidance)<=1500),visibility jsonb not null default '{}'::jsonb check(jsonb_typeof(visibility)='object'),published_at timestamptz,updated_at timestamptz not null default now(),check((status='published' and published_at is not null) or status<>'published'));
create table public.emergency_contacts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,emergency_profile_id uuid not null references public.emergency_profiles(id) on delete cascade,name text not null check(char_length(name) between 1 and 80),relationship text check(char_length(relationship)<=60),phone text not null check(phone ~ '^\+[1-9][0-9]{7,14}$'),is_public boolean not null default false,sort_order smallint not null default 0,created_at timestamptz not null default now());
create table public.consent_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,event_type text not null,document_version text not null,purpose text not null,authorized_fields jsonb not null default '[]',created_at timestamptz not null default now(),revoked_at timestamptz);
create table private.product_batches(id uuid primary key default gen_random_uuid(),name text not null,quantity integer not null check(quantity between 1 and 1000),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table private.products(id uuid primary key default gen_random_uuid(),public_code text not null unique check(public_code ~ '^[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{5}$'),nfc_token_hash bytea not null unique check(octet_length(nfc_token_hash)=32),activation_secret_hash text not null check(char_length(activation_secret_hash) between 40 and 255),batch_id uuid references private.product_batches(id),status private.product_status not null default 'available',owner_id uuid references auth.users(id),activated_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((status='available' and owner_id is null and activated_at is null) or (status in ('active','blocked') and owner_id is not null and activated_at is not null) or status='revoked'));
create index emergency_profiles_user_id_idx on public.emergency_profiles(user_id);create index emergency_contacts_profile_id_idx on public.emergency_contacts(emergency_profile_id);create index emergency_contacts_user_id_idx on public.emergency_contacts(user_id);create index consent_events_user_id_idx on public.consent_events(user_id);create index product_batches_created_by_idx on private.product_batches(created_by);create index products_batch_id_idx on private.products(batch_id) where batch_id is not null;create index products_owner_id_idx on private.products(owner_id) where owner_id is not null;create index products_status_idx on private.products(status);
create table public.user_products(product_id uuid primary key references private.products(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,public_code text not null unique check(public_code ~ '^[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{5}$'),status text not null check(status in ('active','blocked','revoked')),activated_at timestamptz not null,updated_at timestamptz not null default now());
create index user_products_user_id_idx on public.user_products(user_id);
alter table public.profiles enable row level security;alter table public.emergency_profiles enable row level security;alter table public.emergency_contacts enable row level security;alter table public.consent_events enable row level security;alter table public.user_products enable row level security;
create policy profiles_select on public.profiles for select to authenticated using((select auth.uid())=user_id);create policy profiles_insert on public.profiles for insert to authenticated with check((select auth.uid())=user_id);create policy profiles_update on public.profiles for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy emergency_profiles_select on public.emergency_profiles for select to authenticated using((select auth.uid())=user_id);create policy emergency_profiles_insert on public.emergency_profiles for insert to authenticated with check((select auth.uid())=user_id);create policy emergency_profiles_update on public.emergency_profiles for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy contacts_select on public.emergency_contacts for select to authenticated using((select auth.uid())=user_id and exists(select 1 from public.emergency_profiles p where p.id=emergency_profile_id and p.user_id=(select auth.uid())));create policy contacts_insert on public.emergency_contacts for insert to authenticated with check((select auth.uid())=user_id and exists(select 1 from public.emergency_profiles p where p.id=emergency_profile_id and p.user_id=(select auth.uid())));create policy contacts_update on public.emergency_contacts for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id and exists(select 1 from public.emergency_profiles p where p.id=emergency_profile_id and p.user_id=(select auth.uid())));create policy contacts_delete on public.emergency_contacts for delete to authenticated using((select auth.uid())=user_id);
create policy consent_select on public.consent_events for select to authenticated using((select auth.uid())=user_id);create policy consent_insert on public.consent_events for insert to authenticated with check((select auth.uid())=user_id);
create policy user_products_select on public.user_products for select to authenticated using((select auth.uid())=user_id);
revoke all on all tables in schema public from anon,authenticated;grant select,insert,update on public.profiles,public.emergency_profiles to authenticated;grant select,insert,update,delete on public.emergency_contacts to authenticated;grant select,insert on public.consent_events to authenticated;grant select on public.user_products to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('profile-photos','profile-photos',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy photo_select on storage.objects for select to authenticated using(bucket_id='profile-photos' and (storage.foldername(name))[1]=(select auth.uid())::text);create policy photo_insert on storage.objects for insert to authenticated with check(bucket_id='profile-photos' and (storage.foldername(name))[1]=(select auth.uid())::text);create policy photo_update on storage.objects for update to authenticated using(bucket_id='profile-photos' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='profile-photos' and (storage.foldername(name))[1]=(select auth.uid())::text);
